-- LABORATÓRIO — tabelas extras do J4c (só dados fictícios). Rode DEPOIS do 03_dados_ficticios.sql, num banco de ensaio.
-- Também deixa joiners.id numerando sozinho (como na produção, onde o cadastro novo não informa o id).
alter table public.joiners alter column id add generated by default as identity (start with 300000);
create table if not exists public.pre_cadastros (id bigint generated always as identity primary key, nome text not null, cog text not null, email text, whatsapp text, status text not null default 'pendente', created_at timestamptz default now());
create table if not exists public.grupos_envio (codigo text primary key, host_cog text not null, destinatario text, cpf text, cep text, endereco text, numero text, complemento text, bairro text, cidade text, estado text, created_at timestamptz default now());
create table if not exists public.reports (id bigint generated always as identity primary key, joiner_cog text, item_id bigint, item_nome text, ceg text, status text default 'pendente', resposta text, erro_outro text, created_at timestamptz default now());
create table if not exists public.envio_solicitacoes (id bigint generated always as identity primary key, joiner_cog text, joiner_nome text, destinatario text, cpf text, cep text, endereco text, status text default 'pendente', itens jsonb, comprovante_url text, grupo_envio_codigo text, created_at timestamptz default now());
alter table public.pre_cadastros enable row level security; alter table public.grupos_envio enable row level security; alter table public.reports enable row level security; alter table public.envio_solicitacoes enable row level security;
create policy anon_all on public.pre_cadastros for all to anon using (true) with check (true);
create policy anon_all on public.grupos_envio for all to anon using (true) with check (true);
create policy anon_all on public.reports for all to anon using (true) with check (true);
create policy anon_all on public.envio_solicitacoes for all to anon using (true) with check (true);
grant all on all tables in schema public to anon, authenticated, service_role;
