  ('ana', 'Ana Fictícia', 'Ana Fictícia', '000.000.000-01', '01000-000', 'Rua Falsa', 'pendente', '[]', null), ('bia', 'Bia Fictícia', 'Bia Fictícia', '000.000.000-02', '02000-000', 'Rua Teste', 'pendente', '[]', 'ABC234');
-- como na produção, o endereço do aparelho de push é único
alter table public.push_subscriptions add constraint push_subscriptions_endpoint_key unique (endpoint);
